'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let token=location.hash.replace(/^#(?:token=)?/,'')||sessionStorage.getItem('studioToken')||'';
if(token){sessionStorage.setItem('studioToken',token);history.replaceState(null,'',location.pathname)}
let clientId=sessionStorage.getItem('studioClientId');if(!clientId){clientId=crypto.randomUUID();sessionStorage.setItem('studioClientId',clientId)}
const A={boot:null,env:null,project:null,session:{},dirty:false,serial:0,saving:null,timer:null,sessionTimer:null,conflict:null,artifacts:[],artifact:null,runtime:null,evidence:[],compare:[],agentOpen:false,handoff:null,tutorials:[],pendingPort:null,offline:false,localOkay:true,lastSaved:0,generation:null,busy:false,searches:{},pollBusy:false};
const defaults={view:'Architecture',tab:'brief',workingView:'Architect',selectedNode:null,compact:false,panels:{},searches:{},agentTask:'',provider:'codex',tutorial:null};
const B=(label,action,cls='',extra='')=>`<button data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
function saveState(text,cls=''){const e=$('#save-status');e.textContent=text;e.className=cls}
function errorMessage(error){return error?.message||String(error)}
function banner(message,actions=''){const el=$('#notice');el.classList.remove('hidden');el.innerHTML=`<div class="row"><span>${esc(message)}</span><span class="row">${actions}${A.conflict?'':B('×','dismiss-banner','','aria-label="Dismiss"')}</span></div>`}
function clearBanner(){if(!A.conflict)$('#notice').classList.add('hidden')}
async function api(path,options={}){const response=await fetch('/api'+path,{...options,headers:{'X-Studio-Token':token,'Content-Type':'application/json',...(options.headers||{})},body:options.body===undefined?undefined:JSON.stringify(options.body)});let data;try{data=await response.json()}catch{throw new Error('The local service returned an unreadable response. Your browser draft is retained.')};if(!response.ok||data.ok===false){const err=new Error(data.error?.message||data.message||data.stderr||`Request failed (${response.status})`);err.status=response.status;err.details=data.error?.details||data;throw err}return data}
function recoverKey(){return `studioRecovery:${A.env.projectId}:${clientId}`}
function storeRecovery(){if(!A.env||!A.project)return;try{localStorage.setItem(recoverKey(),JSON.stringify({projectId:A.env.projectId,clientId,baseRevision:A.env.revision,serial:A.serial,time:new Date().toISOString(),project:A.project,session:A.session}));A.localOkay=true}catch{A.localOkay=false;saveState('Browser recovery unavailable · saving to disk','error')}}
function retainedBrowserWork(){const found=[];if(!A.env)return found;for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key?.startsWith('studioRecovery:'+A.env.projectId+':'))continue;try{const r=JSON.parse(localStorage.getItem(key));if(r.project&&JSON.stringify(r.project)!==JSON.stringify(A.project))found.push({key,...r})}catch{}}return found.sort((a,b)=>String(b.time).localeCompare(String(a.time)))}
function archiveRecovery(){if(!A.env||!A.project)return;const record={projectId:A.env.projectId,clientId,baseRevision:A.env.revision,serial:A.serial,time:new Date().toISOString(),reason:'Draft retained before using the disk version',project:A.project,session:A.session};try{localStorage.setItem(recoverKey()+':retained:'+crypto.randomUUID(),JSON.stringify(record))}catch{throw new Error('Cannot retain this draft in browser storage. Export recovery before switching to the disk version.')}}
function edit(){if(!A.project)return;A.serial++;A.dirty=true;storeRecovery();saveState('Saving…','saving');clearTimeout(A.timer);A.timer=setTimeout(()=>flush().catch(()=>{}),220)}
function sessionEdit(){if(!A.env)return;storeRecovery();try{localStorage.setItem(`studioSession:${A.env.projectId}:${clientId}`,JSON.stringify(A.session))}catch{};clearTimeout(A.sessionTimer);const projectId=A.env.projectId,session=clone(A.session);A.sessionTimer=setTimeout(()=>api(`/projects/${projectId}/session`,{method:'PUT',body:{session}}).catch(e=>banner('Session save failed: '+e.message)),200)}
async function flush(){clearTimeout(A.timer);if(A.saving){await A.saving;if(A.dirty&&!A.conflict)return flush();return !A.conflict}if(!A.dirty||!A.env)return true;if(A.conflict)return false;const envId=A.env.projectId,serial=A.serial,snapshot=clone(A.project),session=clone(A.session),rev=A.env.revision;A.saving=(async()=>{try{const result=await api(`/projects/${envId}`,{method:'PUT',body:{expectedRevision:rev,clientMutationId:`${clientId}:${serial}:${Date.now()}`,project:snapshot,session}});if(A.env?.projectId!==envId)return;A.env={...A.env,...result};A.lastSaved=Date.now();if(serial===A.serial){A.dirty=false;try{localStorage.removeItem(recoverKey())}catch{};saveState('Saved to disk','saved')}else{storeRecovery();saveState('Saving newer edits…','saving')}A.offline=false;$('#connection').classList.add('hidden')}catch(e){if(A.env?.projectId!==envId)return;if(e.status===409){A.conflict=e;saveState('Conflict · draft retained','error');banner('The disk version changed. Your edits are retained for recovery.',B('Inspect current disk version','inspect-disk')+B('Keep my draft as a new project','fork-draft')+B('Use disk version','use-disk'))}else{A.offline=true;saveState(A.localOkay?'Save failed · browser recovery retained':'Save failed · export now','error');banner(e.message,B('Retry save','retry-save')+B('Export recovery','export-recovery'))}}})().finally(()=>{A.saving=null});await A.saving;if(A.dirty&&!A.conflict&&!A.offline)return flush();return !A.dirty}
function setEnvelope(env,sessionOverride){if(A.env?.projectId!==env.projectId){$('#notice').classList.add('hidden');$('#notice').replaceChildren();A.artifacts=[];A.jobId=null;A.pendingArtifact=null;A.sourceInventory=null;A.sourcePlan=null;A.repositories=null}A.env=env;A.project=clone(env.project);A.session={...clone(defaults),...(env.session||{}),...(sessionOverride||{})};A.dirty=false;A.conflict=null;A.artifact=null;A.serial=0;A.evidence=[];A.compare=[];A.runtime=null;A.deployment=null;A.handoff=null;A.searches=A.session.searches||{};ensureStudio();saveState('Saved to disk','saved');}
function ensureStudio(){const p=A.project;p.studio=p.studio||{};p.studio.brief=p.studio.brief||{};p.studio.behavior=p.studio.behavior||[];p.studio.modules=p.studio.modules||{};p.studio.criteria=p.studio.criteria||[];for(const n of p.nodes||[])p.studio.modules[n.id]=p.studio.modules[n.id]||{role:'Unassigned',unit:'unassigned',sourcePaths:[]};p.studio.deployment=p.studio.deployment||{units:[]};p.studio.deployment.units=p.studio.deployment.units||[]}
function name(){return A.project?.system?.name||'Untitled system'}
function selected(){return A.project?.nodes?.find(n=>n.id===A.session.selectedNode)||A.project?.nodes?.[0]}
function moduleMeta(n){return A.project.studio.modules[n.id]||{role:'Unassigned',unit:'unassigned',sourcePaths:[]}}
function mutationFailure(e){banner(errorMessage(e));saveState(A.dirty?'Draft retained':'Saved to disk',A.dirty?'error':'saved')}
async function openProject(id){if(typeof flushPhysics==='function')await flushPhysics();if(!await flush())return;const env=await api('/projects/'+id);setEnvelope(env);try{const saved=JSON.parse(localStorage.getItem(`studioSession:${id}:${clientId}`));if(saved)A.session={...A.session,...saved}}catch{};sessionStorage.setItem('studioActiveProject',id);if(A.session.tutorial)tutorialProof('projectReopened');render();const recovery=[];try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith('studioRecovery:'+id+':')){try{const r=JSON.parse(localStorage.getItem(k));if(r.project&&JSON.stringify(r.project)!==JSON.stringify(A.project))recovery.push({key:k,...r})}catch{}}}}catch{A.localOkay=false}if(recovery.length){A.recoveries=recovery;banner('Unsaved browser work is available for this project.',B('Review recovered work','browser-recovery'))}refreshArtifacts();}
async function refreshBootstrap(){A.boot=await api('/bootstrap');return A.boot}
function recent(){return A.boot?.projects||A.boot?.recentProjects||[]}
function landing(){ $('#workbench').classList.add('hidden');$('#agent-launcher').classList.add('hidden');$('#agent-drawer').classList.add('hidden');$('#landing').classList.remove('hidden');$('#project-name').textContent='';$('#landing').innerHTML=`<section class="welcome"><p>Architecture · Model checking</p><h1>Build the system.<br>Keep its engineering connected.</h1><p>Start from a brief, a supported model, or a small working example.</p><div class="entry-grid"><button data-action="new"><strong>＋ New project</strong><span>Define its purpose, behavior and architecture.</span></button><button data-action="open"><strong>▤ Open project or model</strong><span>Open project.json or import a .rossystem file from disk.</span></button><button data-action="starter"><strong>◇ Learn with a ROS example</strong><span>A separate publisher/subscriber practice project with real artifacts.</span></button></div><button data-engineering="open-source-workspace">Import an existing ROS source workspace</button><div class="row between"><h2>Recent projects</h2>${B('Tutorials','tutorials')}</div>${recent().map(p=>`<article class="project-card"><div><strong>${esc(p.name||p.project?.system?.name||p.projectId||p.id)}</strong><br><code>${esc(p.root||p.path||'')}</code></div><button data-open-project="${esc(p.projectId||p.id)}">Open</button></article>`).join('')||'<p class="muted">No saved projects yet. A new project gets its own directory and recovery history.</p>'}<p class="mini muted">Project and job storage: ${esc(A.boot?.storageRoot||A.boot?.roots?.storage||'~/ros-studio')}.</p></section>`}
function nav(){const stages=['Architecture','Develop','Validate','Deploy'];$('#lifecycle').innerHTML=stages.map((x,i)=>(i?'<span class="arrow" aria-hidden="true">→</span>':'')+`<button data-view="${x}" class="${A.session.view===x?'active':''}" ${A.session.view===x?'aria-current="page"':''} aria-label="${x}" title="${i+1}. ${x}"><span class="circle">${i+1}</span><span class="step-label">${x}</span></button>`).join('');$('#lifecycle').classList.toggle('compact',A.session.compact);$('#compact-navigation').textContent=A.session.compact?'»':'«';$('#compact-navigation').setAttribute('aria-label',(A.session.compact?'Expand':'Collapse')+' lifecycle');$('#compact-navigation').setAttribute('aria-expanded',!A.session.compact);$('#working-view').value=A.session.workingView;$('#project-name').textContent='/ '+name()}
function panelState(){const k=A.session.view;A.session.panels=A.session.panels||{};return A.session.panels[k]||(A.session.panels[k]={left:false,right:false,swap:false,leftWidth:230,rightWidth:285})}
function context(){const p=panelState(),deploy=A.session.view==='Deploy';$('#contextbar').innerHTML=`<span>${esc(name())} / ${esc(A.session.view)} <span class="tag">${esc(A.session.workingView)} view</span></span><div class="row">${B('Tools ▾','tools')}${deploy?'':B(p.left?'Show explorer':'Hide explorer','toggle-left')}${B(p.right?'Show inspector':'Hide inspector','toggle-right')}${B('Layout ▾','layout')}</div>`;const w=$('#workspace');w.classList.toggle('left-hidden',p.left||deploy);w.classList.toggle('right-hidden',p.right);w.classList.toggle('swapped',p.swap);w.style.setProperty('--left',p.left||deploy?'0px':p.leftWidth+'px');w.style.setProperty('--right',p.right?'0px':p.rightWidth+'px');$('#root-path').textContent=A.env.root;$('#sync-status').textContent=`${A.env.modelState||'draft'} · project revision ${A.env.revision}`}
function render(){if(!A.project){landing();return}$('#landing').classList.add('hidden');$('#workbench').classList.remove('hidden');$('#agent-launcher').classList.toggle('hidden',A.session.workingView==='Customer');nav();if(typeof renderShortcuts==='function')renderShortcuts();context();if(A.session.view==='Architecture')architecture();if(A.session.view==='Develop')develop();if(A.session.view==='Validate')validateView();if(A.session.view==='Deploy')deployView();renderAgent();renderTutorial();requestAnimationFrame(drawEdges)}
function tabs(items){return '<div class="subnav">'+items.map(([key,label])=>`<button data-tab="${key}" class="${A.session.tab===key?'active':''}">${label}</button>`).join('')+'</div>'}
function architecture(){if(!['brief','system'].includes(A.session.tab))A.session.tab='system';if(A.session.workingView==='Customer'){customerOverview();return}if(A.session.tab==='brief')brief();else systemView();$('#main').insertAdjacentHTML('afterbegin',tabs([['brief','Brief & behavior'],['system','System']]))}
function brief(){const b=A.project.studio.brief;$('#explorer').innerHTML='<h2>Project definition</h2><p class="mini muted">Define the task, its limits, and how you will know it works.</p><ol><li>Purpose and constraints</li><li>Acceptance criteria</li><li>Behavior and recovery</li><li>System architecture</li></ol><div class="hint">Edits save automatically. Invalid or unfinished model drafts remain recoverable.</div>';$('#main').innerHTML=`<h1>What should this system do?</h1><p class="muted">Use plain language first. Link behavior to modules as the model develops.</p><form id="brief-form"><label class="field">Purpose<textarea data-brief="purpose" rows="2" placeholder="What job must the robot perform?">${esc(b.purpose)}</textarea></label><div class="grid2"><label class="field">Constraints<textarea data-brief="constraints" placeholder="Robot, payload, workspace and operating limits…">${esc(b.constraints)}</textarea></label><label class="field">Acceptance criteria<textarea data-brief="acceptance" placeholder="What observable results will count as success?">${esc(b.acceptance)}</textarea></label></div><details><summary>Users and operating environment</summary><label class="field">Users<input data-brief="users" value="${esc(b.users)}"></label><label class="field">Environment<input data-brief="environment" value="${esc(b.environment)}"></label></details><section class="section"><div class="row between"><h2>Behavior & recovery</h2>${B('+ Add step','add-behavior')}</div>${A.project.studio.behavior.map((s,i)=>`<div class="behavior-step"><span class="circle">${i+1}</span><label class="field">Action<input data-behavior="${i}" data-field="action" value="${esc(s.action)}"></label><label class="field">Responsible module<select data-behavior="${i}" data-field="moduleId"><option value="">Unassigned</option>${A.project.nodes.map(n=>`<option value="${n.id}" ${s.moduleId===n.id?'selected':''}>${esc(n.label)}</option>`).join('')}</select></label><label class="field">When<input data-behavior="${i}" data-field="condition" value="${esc(s.condition)}"></label><label class="field">Criterion<select data-behavior="${i}" data-field="criterionId"><option value="">Unlinked</option>${(A.project.studio.criteria||[]).map(c=>`<option value="${c.id}" ${s.criterionId===c.id?'selected':''}>${esc(c.text)}</option>`).join('')}</select></label><label class="field">On failure<input data-behavior="${i}" data-field="recovery" value="${esc(s.recovery)}"></label><button data-delete-behavior="${i}" aria-label="Remove behavior step ${i+1}">×</button></div>`).join('')||'<p class="hint">Add the main steps and recovery decisions. This written sequence is not executable behavior code.</p>'}</section>${criteriaPanel()}<div class="toolbar"><span class="mini muted">Stored in project.json. See the save status above.</span>${B('Continue to system','to-system','primary')}</div></form>`;$('#inspector').innerHTML=`<h2>From intent to implementation</h2><p class="mini">Brief → modules → interfaces → files → checks → deployment.</p>${B('Prepare a coding task','agent')}<div class="section"><h3>Model foundation</h3><p class="mini">CoreSense responsibilities are linked metadata. The existing RosTooling generator emits supported ROS contracts; unsupported behavior semantics remain explicit.</p></div>`}
function templates(){return A.boot?.catalogue||[]}
function catalog(){const term=A.session.searches?.catalogue||'';return `<h2>Catalogue</h2><button data-engineering="repositories">Source repositories</button><input id="catalogue-search" class="search" data-search="catalogue" placeholder="Find a package or node…" aria-label="Search catalogue" value="${esc(term)}"><p class="mini muted">Drag into the system or choose Add. These are model contracts, not qualified deployment recipes.</p><div id="catalogue">${templates().map((t,i)=>`<article class="library-card ${(`${t.name} ${t.package}`).toLowerCase().includes(term.toLowerCase())?'':'hidden'}" draggable="true" data-template="${i}"><h3>${esc(t.name)}</h3><p>${esc(t.package)}</p><button data-add-template="${i}">+ Add</button><button data-template-info="${i}">Provenance</button></article>`).join('')}</div>${B('+ Define custom node','custom-node')}<p class="mini muted section">Upstream source and model provenance remain visible. Adding a model does not clone a repository or start software.</p>`}
function nodeCard(n,position){const m=moduleMeta(n),x=position?.x??n.x??30,y=position?.y??n.y??30;return `<article class="node ${selected()?.id===n.id?'selected':''}" data-node="${esc(n.id)}" style="left:${x}px;top:${y}px"><button class="node-head" data-select-node="${esc(n.id)}" title="Select or drag ${esc(n.label)}"><small>${esc(m.role||'Unassigned role')}</small><strong>${esc(n.label)}</strong></button><div class="node-body"><code>${esc(n.pkg)} / ${esc(n.node)}</code>${(n.ifaces||[]).map(f=>`<button class="port ${['pub','ss','as'].includes(f.kind)?'out':'in'} ${A.pendingPort?.i===f.id?'pending':''}" data-port-node="${n.id}" data-port-id="${f.id}" title="${esc(f.type||'Type unknown')}">${esc(f.kind)} · ${esc(f.name)}</button>`).join('')}</div></article>`}
function edgeTitle(c){const a=A.project.nodes.find(n=>n.id===c.from.n),b=A.project.nodes.find(n=>n.id===c.to.n),i=a?.ifaces.find(f=>f.id===c.from.i);return `${a?.label||'?'} → ${b?.label||'?'} · ${i?.name||'interface'}`}
function graph(){const nodes=A.project.nodes,width=Math.max(850,...nodes.map(n=>(n.x||0)+300)),height=Math.max(600,...nodes.map(n=>(n.y||0)+Math.max(210,90+(n.ifaces?.length||0)*38))),zoom=A.session.canvasZoom||1;return `<div class="canvas-shell"><div class="canvas-wrap"><div id="canvas" class="canvas" data-canvas="true" style="min-width:${width}px;min-height:${height}px;zoom:${zoom}">${nodes.map(n=>nodeCard(n)).join('')}<svg class="edges" aria-hidden="true"></svg>${!nodes.length?'<div class="empty"><h2>Add your first module</h2><p>Use Add in the catalogue or drag a contract onto this canvas. You can also create a custom node.</p></div>':''}</div></div><div class="canvas-controls" role="group" aria-label="Canvas zoom"><button data-canvas-zoom-out aria-label="Zoom out">−</button><button data-canvas-fit aria-label="Fit view">Fit view</button><button data-canvas-zoom-in aria-label="Zoom in">+</button><span class="mini muted">${Math.round(zoom*100)}%</span></div></div><div class="edge-list">${A.project.connections.map((c,i)=>`<button data-edge="${i}">${esc(edgeTitle(c))}<br><span class="mini muted">${esc(connectionPolicies(c))}</span></button>`).join('')}</div>`}
function zoomCanvas(mult){A.session.canvasZoom=Math.max(.2,Math.min(2,Math.round((A.session.canvasZoom||1)*mult*100)/100));sessionEdit();render()}
function fitCanvas(){const wrap=$('.canvas-wrap'),canvas=$('[data-canvas]');if(!wrap||!canvas)return;const prior=canvas.style.zoom;canvas.style.zoom=1;const contentW=canvas.scrollWidth,contentH=canvas.scrollHeight;canvas.style.zoom=prior||1;const scale=Math.min(wrap.clientWidth/Math.max(1,contentW),wrap.clientHeight/Math.max(1,contentH));A.session.canvasZoom=Math.max(.2,Math.min(1.5,Math.round(scale*100)/100));sessionEdit();render()}
function systemView(){ $('#explorer').innerHTML=catalog();$('#main').innerHTML=`<div class="row between"><div><h1>System architecture</h1><p class="mini muted">Declared contracts and their ROS implementations.</p></div>${B('Check model','validate','primary','id="validate-model"')}</div><div class="toolbar"><span class="tag">${A.project.nodes.length} nodes · ${A.project.connections.length} connections</span><input class="search" id="graph-search" placeholder="Find node, package or role…" aria-label="Search graph" style="max-width:300px"></div>${graph()}<p class="mini muted">Drag node headers to arrange. Connect by choosing a publisher/server port, then a compatible subscriber/client.</p>`;nodeInspector()}
function nodeInspector(){const n=selected();if(!n){$('#inspector').innerHTML='<h2>No node selected</h2><p>Add a contract to inspect its identity, ports and deployment mapping.</p>';return}A.session.selectedNode=n.id;const m=moduleMeta(n);$('#inspector').innerHTML=`<h2>${esc(n.label)}</h2><span class="tag">${esc(n.backing==='cat'?'Catalogue contract':'Project-owned model')}</span><label class="field">Instance label<input data-node-field="label" value="${esc(n.label)}"></label><label class="field">CoreSense responsibility<select data-module-field="role">${['Unassigned','Afferent','Core','Efferent','Meta','Supporting'].map(x=>`<option ${x===(m.role||'Unassigned')?'selected':''}>${x}</option>`).join('')}</select></label><p class="mini">${roleDescription(m.role)}</p><label class="field">Deployment unit<input data-module-field="unit" value="${esc(m.unit||'unassigned')}" placeholder="robot"></label><label class="field">Namespace<input data-node-field="namespace" value="${esc(n.namespace)}"></label><dl><dt class="mini muted">Model ID</dt><dd><code>${esc(n.id)}</code></dd><dt class="mini muted">Implementation</dt><dd><code>${esc(n.pkg)}.${esc(n.node)}</code></dd></dl><p class="mini">Source: ${esc(m.repository||'Not linked')}</p><button data-resolve-node-source="${esc(n.id)}">Resolve implementation source</button><div class="section"><h3>Interfaces</h3>${(n.ifaces||[]).map(f=>`<button class="list-button" data-edit-iface="${f.id}">${esc(f.kind)} · ${esc(f.name)}<br><small>${esc(f.type||'Unresolved type')}</small></button>`).join('')}${n.backing==='hand'?B('+ Add interface','add-interface'):''}</div><section class="section"><h3>Responsible behavior</h3>${A.project.studio.behavior.filter(s=>s.moduleId===n.id).map(s=>`<p class="mini">${esc(s.action)} · ${esc(s.condition)}<br>Recovery: ${esc(s.recovery)}</p>`).join('')||'<p class="mini">No behavior linked yet.</p>'}</section><div class="section row">${B('Relevant files','develop')}${B('Remove node','remove-node','danger')}</div>`}
function drawEdges(){const canvas=$('[data-canvas]');if(!canvas)return;const svg=canvas.querySelector('.edges'),r=canvas.getBoundingClientRect();const collapsed=A.session.collapsedUnits||{};
  // getBoundingClientRect() on anything inside a CSS-`zoom`ed canvas already reports real,
  // zoomed screen pixels. The <svg> is itself a child of that same zoomed canvas, so it would
  // get zoomed a SECOND time on top of coordinates already expressed in zoomed pixels; dividing
  // by the current zoom here converts back to the SVG's own local (unzoomed) coordinate space
  // before drawing, which is what actually lands the paths back on the real port positions.
  const z=A.session.canvasZoom||1;
  function unitOf(ep){const n=A.project.nodes.find(n=>n.id===ep.n);return n&&(moduleMeta(n).unit||'unassigned')}function point(ep,out){let el=canvas.querySelector(`[data-port-node="${CSS.escape(ep.n)}"][data-port-id="${CSS.escape(ep.i)}"]`);if(!el){const n=A.project.nodes.find(n=>n.id===ep.n);const unit=n&&moduleMeta(n).unit;el=canvas.querySelector(`[data-unit="${CSS.escape(unit||'unassigned')}"]`)}if(!el)return null;const b=el.getBoundingClientRect();return {x:((out?b.right:b.left)-r.left)/z,y:(b.top+b.height/2-r.top)/z}}svg.innerHTML='<defs><marker id="arrowhead" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" style="fill:#6289b0;stroke:none"/></marker></defs>'+A.project.connections.map(c=>{
  // A connection whose two endpoints both sit inside the same collapsed deployment unit has
  // nowhere real to point: both ports resolve to that one unit box, drawing an arrow out of its
  // edge and straight back into itself. It is genuinely internal to the collapsed unit, so skip
  // drawing it rather than render a self-loop; it reappears once that unit is expanded again.
  const fu=unitOf(c.from),tu=unitOf(c.to);if(fu&&tu&&fu===tu&&collapsed[fu])return '';
  const a=point(c.from,true),b=point(c.to,false);if(!a||!b)return '';const d=b.x>a.x?`M${a.x} ${a.y}C${a.x+45} ${a.y},${b.x-45} ${b.y},${b.x} ${b.y}`:`M${a.x} ${a.y}L${a.x+18} ${a.y}L${a.x+18} ${Math.max(a.y,b.y)+35}L${b.x-18} ${Math.max(a.y,b.y)+35}L${b.x-18} ${b.y}L${b.x} ${b.y}`;return `<path d="${d}" marker-end="url(#arrowhead)"/>`}).join('')}
