function connect(nid,iid){const n=A.project.nodes.find(x=>x.id===nid),f=n.ifaces.find(x=>x.id===iid);if(['pub','ss','as'].includes(f.kind)){A.pendingPort={n:nid,i:iid};render();banner('Select the matching subscriber or client port.');return}if(!A.pendingPort){banner('Choose a publisher or server port first.');return}const sn=A.project.nodes.find(n=>n.id===A.pendingPort.n),sf=sn.ifaces.find(x=>x.id===A.pendingPort.i);if(!({pub:'sub',ss:'sc',as:'ac'}[sf.kind]===f.kind&&sf.type&&sf.type===f.type)){banner('These port kinds or types do not match. No connection added.');return}if(!A.project.connections.some(c=>c.from.n===sn.id&&c.from.i===sf.id&&c.to.n===n.id&&c.to.i===f.id))A.project.connections.push({id:crypto.randomUUID(),from:{n:sn.id,i:sf.id},to:{n:n.id,i:f.id}});A.pendingPort=null;edit();clearBanner();render()}
