document.addEventListener('input',e=>{const t=e.target;if(t.dataset.brief!==undefined){A.project.studio.brief[t.dataset.brief]=t.value;edit()}if(t.dataset.behavior!==undefined&&t.tagName!=='SELECT'){A.project.studio.behavior[+t.dataset.behavior][t.dataset.field]=t.value;edit()}if(t.dataset.nodeField){selected()[t.dataset.nodeField]=t.value;edit()}if(t.dataset.moduleField&&t.tagName!=='SELECT'){const n=selected();A.project.studio.modules[n.id]={...moduleMeta(n),[t.dataset.moduleField]:t.value};edit()}if(t.id==='agent-task'){A.session.agentTask=t.value;A.handoff=null;sessionEdit()}if(t.dataset.search){A.session.searches=A.session.searches||{};A.session.searches[t.dataset.search]=t.value;sessionEdit();const term=t.value.toLowerCase();const selector={catalogue:'.library-card',modules:'#explorer .list-button',artifacts:'.artifact-row',evidence:'.evidence-row'}[t.dataset.search];$$(selector).forEach(el=>el.classList.toggle('hidden',!el.textContent.toLowerCase().includes(term)))}if(t.id==='graph-search'){const term=t.value.toLowerCase();$$('[data-node]').forEach(el=>{const n=A.project.nodes.find(n=>n.id===el.dataset.node),match=(n.label+' '+n.pkg+' '+JSON.stringify(moduleMeta(n))).toLowerCase().includes(term);el.classList.toggle('match',!!term&&match);el.classList.toggle('dim',!!term&&!match)})}});
